-- An option value's swatch: a colour (#rrggbb, lowercase) and/or an image
-- from Files, which the storefront's swatch layout and product cards draw.
-- Expand-only: the columns are added in place with inline checks, so
-- product_option_values and its triggers are not rebuilt. A file a swatch
-- uses is never deleted under it (Files counts it as a place; restrict).
ALTER TABLE `product_option_values` ADD `swatch_color` text CONSTRAINT `product_option_values_swatch_color_check` CHECK (`swatch_color` IS NULL OR (length(`swatch_color`) = 7 AND `swatch_color` GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'));
--> statement-breakpoint
ALTER TABLE `product_option_values` ADD `swatch_media_id` text REFERENCES media(id) ON DELETE restrict;
--> statement-breakpoint
CREATE INDEX `product_option_values_swatch_media_idx` ON `product_option_values` (`swatch_media_id`) WHERE "product_option_values"."swatch_media_id" IS NOT NULL;
--> statement-breakpoint
-- The swatch columns are visible: a swatch edit advances the product
-- (generated by scripts/cache-dep-triggers.ts).
DROP TRIGGER IF EXISTS `cdep_product_option_values_upd`;
--> statement-breakpoint
CREATE TRIGGER `cdep_product_option_values_upd` AFTER UPDATE ON `product_option_values`
WHEN (OLD.`id` IS NOT NEW.`id` OR OLD.`option_definition_id` IS NOT NEW.`option_definition_id` OR OLD.`value` IS NOT NEW.`value` OR OLD.`normalized_value` IS NOT NEW.`normalized_value` OR OLD.`position` IS NOT NEW.`position` OR OLD.`deleted_at` IS NOT NEW.`deleted_at` OR OLD.`swatch_color` IS NOT NEW.`swatch_color` OR OLD.`swatch_media_id` IS NOT NEW.`swatch_media_id`)
BEGIN
  INSERT INTO `cache_dep` (`dep`, `seq`)
  SELECT key_rows.dep, COALESCE((SELECT `seq` FROM `cache_clock` WHERE `id` = 1), 0) + 1 FROM (SELECT key_list.value AS dep FROM json_each(json_array('p:' || (SELECT `product_id` FROM `product_option_definitions` WHERE `id` = NEW.`option_definition_id`), 't:product_option_values')) AS key_list UNION SELECT 'p:' || key_ref_1.ref FROM (SELECT assigning_sku.product_id AS ref FROM product_variant_option_values AS assignment JOIN product_variants AS assigning_sku ON assigning_sku.id = assignment.variant_id WHERE assignment.option_value_id = NEW.id) AS key_ref_1) AS key_rows
  WHERE key_rows.dep IS NOT NULL AND COALESCE((SELECT `coarse` FROM `cache_clock` WHERE `id` = 1), 0) = 0
  UNION ALL SELECT 'store', COALESCE((SELECT `seq` FROM `cache_clock` WHERE `id` = 1), 0) + 1 WHERE COALESCE((SELECT `coarse` FROM `cache_clock` WHERE `id` = 1), 0) = 1
  ON CONFLICT (`dep`) DO UPDATE SET `seq` = excluded.`seq`;
END;
